features.example:
// .claude/settings.json
{
  "permissions": {
    "allow": ["Bash(npm test)"],
    "deny": ["Read(.env)"]
  },
  "env": {
    "DEBUG": "true"
  },
  "defaultMode": "plan"
}

// .claude/settings.json
{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash(rm|rmdir)",
        "hooks": [
          "if [[ \"$CLAUDE_TOOL_INPUT\" == *'/home'* ]]; then echo 'Blocked'; exit 1; fi"
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Edit(**/*.ts)",
        "hooks": [
          "npx prettier --write \"$CLAUDE_TOOL_INPUT_PATH\""
        ]
      }
    ]
  }
}

# Inside a session, ask Claude:
> Start the dev server in background, then refactor auth.ts

# Claude calls Bash with run_in_background=true
# Then monitors with BashOutput periodically

# Or in the Agent SDK:
await query({
  prompt: 'npm run dev (background) then update header',
  options: { allowedTools: ['Bash', 'Edit', 'BashOutput'] }
})

// .mcp.json
{
  "mcpServers": {
    "postgres": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-postgres",
               "postgresql://readonly:pass@db/analytics"]
    },
    "linear": {
      "command": "npx",
      "args": ["-y", "@linear/mcp-server"]
    }
  }
}

// Or via CLI:
// claude mcp add --transport stdio db -- npx -y @org/server

// Allow only the safe read-side
// .claude/settings.json
{
  "permissions": {
    "allow": ["Read(**)", "Glob(**)", "Grep(**)"],
    "deny": ["Bash(*)", "Write(**)", "Edit(**)"]
  }
}

// Or per invocation
// claude -p --allowedTools Read,Grep "find TODOs"

// .claude/settings.json
{
  "permissions": {
    "allow": [
      "Bash(npm test)",
      "Bash(npm run build)",
      "Read(src/**/*.ts)",
      "Edit(src/**/*.ts)"
    ],
    "deny": [
      "Bash(rm -rf:*)",
      "Read(.env)",
      "Read(.env.*)",
      "Edit(.git/**)"
    ]
  }
}
